function dates({ propertyId, recipient, chatId }) {
  if (
    !/^\d+$/.test(propertyId) ||
    typeof recipient !== "string" ||
    !/^\S+@\S+\.\S+$/.test(recipient) ||
    typeof chatId !== "string" ||
    !chatId ||
    chatId.startsWith("YOUR_")
  )
    throw Error("Configure property, email and Telegram chat");
  const today = new Date(),
    iso = (d) => d.toISOString().slice(0, 10),
    end = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate() - 1)),
    start = new Date(end.getTime() - 6 * 86400000),
    year = (d) => {
      let x = new Date(d);
      x.setUTCFullYear(x.getUTCFullYear() - 1);
      return x;
    };
  const priorEnd = year(end),
    priorStart = new Date(priorEnd.getTime() - 6 * 86400000);
  return {
    propertyId,
    recipient,
    chatId,
    recentStart: iso(start),
    recentEnd: iso(end),
    previousStart: iso(priorStart),
    previousEnd: iso(priorEnd),
  };
}

return [
  {
    json: dates({
      propertyId: "YOUR_PROPERTY_ID",
      recipient: "report@example.com",
      chatId: "configured-separately",
    }),
  },
];

const r = $input.first().json.body,
  rows = r?.rows ?? [],
  count = r?.rowCount ?? (rows.length === 0 ? 0 : null);
if (!r || !Array.isArray(rows) || !Number.isInteger(count) || count !== rows.length || count > 8)
  throw Error("Invalid analytics report");
const a = Array(8).fill(0);
for (const row of rows) {
  if (
    !Array.isArray(row.dimensionValues) ||
    !/^\d{8}$/.test(row.dimensionValues[0]?.value) ||
    !Array.isArray(row.metricValues) ||
    row.metricValues.length !== 8
  )
    throw Error("Invalid analytics row");
  row.metricValues.forEach((x, i) => {
    const n = Number(x.value);
    if (typeof x.value !== "string" || !Number.isFinite(n)) throw Error("Invalid metric");
    a[i] += n;
  });
}
for (const i of [3, 4, 6]) if (rows.length) a[i] /= rows.length;
return [
  {
    json: {
      sum_Aufrufe: a[0],
      sum_Nutzer: a[1],
      sum_Sitzungen: a[2],
      average_Sitzungen_pro_Nutzer: a[3],
      average_Sitzungsdauer: a[4],
      sum_Käufe: a[5],
      average_Revenue_pro_Kauf: a[6],
      sum_Revenue: a[7],
    },
    pairedItem: { item: 0 },
  },
];

